import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Brand-specific trend captions","description":"","frontmatter":{},"headers":[],"relativePath":"feature/brand-trend-caption-quality/spec.md","filePath":"feature/brand-trend-caption-quality/spec.md"}'),r={name:"feature/brand-trend-caption-quality/spec.md"};function o(s,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="brand-specific-trend-captions" tabindex="-1">Brand-specific trend captions <a class="header-anchor" href="#brand-specific-trend-captions" aria-label="Permalink to &quot;Brand-specific trend captions&quot;">​</a></h1><h2 id="objective-and-user-story" tabindex="-1">Objective and user story <a class="header-anchor" href="#objective-and-user-story" aria-label="Permalink to &quot;Objective and user story&quot;">​</a></h2><p>As a creator, I want suitable trends for my workspace brand and captions that apply my selected trend in the target platform&#39;s style. Gemini remains primary; an economical Claude fallback handles unavailable, empty, invalid or timed-out responses.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Use a separate Claude fallback model (Haiku 5.5), bounded timeouts and no automatic fallback retry loop. Preserve explicit primary Claude configuration.</li><li>Scope brand facts to the workspace and its linked client profile. Do not combine several clients into one invented brand.</li><li>Filter unsuitable/risky trends and remove fabricated fallback trends. Cache by workspace, profile, user description, platform and candidate content.</li><li>User decision 2026-11-05: when industry/product/audience are incomplete, use the user&#39;s description and clearly label recommendations provisional. Never invent missing facts.</li><li>Revalidate a selected trend against brand constraints before caption generation. Do not silently ignore an unsuitable selection.</li><li>Every selected-trend variant includes a concrete connection between trend and brand; platform-specific hook, structure, length, CTA and relevant hashtags. No guarantee of viral reach, invented endorsement or engagement bait.</li><li>Humanizer, existing credit/idempotency and tenant checks remain in force.</li></ul><h2 id="api-and-ui-states" tabindex="-1">API and UI states <a class="header-anchor" href="#api-and-ui-states" aria-label="Permalink to &quot;API and UI states&quot;">​</a></h2><p>Trend-fit accepts optional description and platform; returns provisional status. Existing callers remain valid. UI sends the current description after a debounce and shows a preliminary notice. Loading/error states must not leave an old workspace&#39;s trend selected.</p><p>New text uses aiStudio.trendFit.provisional in both src/i18n/locales/vi/aiStudio.json and src/i18n/locales/en/aiStudio.json. Reuse existing semantic colors and light/dark variants; keyboard controls and layout remain unchanged.</p><h2 id="error-handling-and-edge-cases" tabindex="-1">Error handling and edge cases <a class="header-anchor" href="#error-handling-and-edge-cases" aria-label="Permalink to &quot;Error handling and edge cases&quot;">​</a></h2><p>Provider failure yields the existing unavailable error, never synthetic captions/trends. Invalid selection yields a validation error before LLM caption work. Unknown profile remains provisional, other-brand campaigns permit format study only. Cache changes when source cards change.</p><h2 id="definition-of-done-tests" tabindex="-1">Definition of done / tests <a class="header-anchor" href="#definition-of-done-tests" aria-label="Permalink to &quot;Definition of done / tests&quot;">​</a></h2><p>Focused provider, brand isolation, matching/cache, selected-trend, platform and API tests pass. API-only smoke results are saved without credentials. No UI automation, commit or push.</p><p>Integration follow-up (2026-11-05): changes live directly in the three main repositories, without hardcoded preview addresses. Align ignored local AI Redis/RabbitMQ credentials with existing local Compose configuration, never print credentials. Verify Redis connectivity through the normal AI settings, without replacing other worktrees&#39; running services.</p><p>Runtime bug follow-up: user confirmed Web3000 uses <code>_wt/web-trend-boards</code>, whose caption generate/refine/adapt calls still bypass the shared credit-request helper. Missing mandatory idempotency/workspace headers reproduces HTTP400 before provider work. Apply the narrow shared-helper fix to that active worktree, preserving its existing features; verify through Gateway8080 → Business8081 → AI8082. No UI automation, commit or push.</p><p>Second runtime failure: after correct headers, AI8082 returns a failed/unknown outcome after 86 seconds. Its active source still uses the older Gemini retry/Opus fallback and stale Redis settings despite using the same provider keys as the working preview. Apply only the already-tested provider fallback patch/configuration to this AI worktree and synchronize its ignored local dependency settings; restart this API with its existing role, leaving unrelated source untouched.</p><p>Confirmed provider mechanism: the active worktree&#39;s Anthropic client inherits a DeepSeek endpoint from the launching shell. The identical key returns OK on api.anthropic.com and 401 on the inherited endpoint. Bring over main&#39;s existing explicit Anthropic URL and add a regression test against shell endpoint leakage. No key replacement is required.</p><p>Local pricing follow-up (2026-11-06): user confirmed the editor&#39;s generic Generate with AI text button uses CONTENT_GENERATE, a distinct billable operation from free CAPTION_VARIANTS. Local price table is empty. User explicitly selected enabled CONTENT_GENERATE at0 credits per call for local testing. Apply through existing Admin price API with expectedRevision0, leaving all other prices/wallet data unchanged; then test this exact generic content route.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>New brand profile forms, new database schema, paid video generation, publishing and guarantees of virality.</p>',19)])])}const f=a(r,[["render",o]]);export{u as __pageData,f as default};
